import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n, q = map(int, input[index].split())
        s = input[index + 1]
        index += 2
        queries = [tuple(map(int, input[index + i].split())) for i in range(q)]
        index += q
        for l, r in queries:
            sub = s[l-1:r]
            if len(sub) < 2:
                results.append("NO")
            else:
                unique_chars = set(sub)
                if len(unique_chars) == 1 and list(unique_chars)[0] == '1':
                    results.append("NO" if len(sub) == 2 else "YES")
                elif len(unique_chars) == 1 and list(unique_chars)[0] == '':
                    results.append("NO")
                else:
                    results.append("YES")
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
